(function(){
'use strict';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>'PKR '+Number(n||0).toLocaleString('en-PK',{maximumFractionDigits:2}),date=s=>new Date(s).toLocaleDateString('en-GB');
function create(api){
 let access={},identity=null,tab='overview',page=1,refPage=1,orders={rows:[],total:0},generation=0;
 const invite=code=>{const u=new URL(location.origin+location.pathname);u.searchParams.set('vendor',code);u.hash='vendor-register';return u.href};
 const metric=(label,value)=>`<div class="vendor-metric"><span>${label}</span><strong>${value}</strong></div>`;
 function setup(){
  const registration=document.createElement('section');registration.id='page-vendor-register';registration.className='page';registration.innerHTML=`<div class="vendor-registration"><header class="vendor-heading"><div><small>SELL ON MARKET IS ONLINE</small><h1>Register your store</h1><p>Register your vendor account, or sign in with your existing email. Verify your email, submit your business details, then accept the company agreement.</p></div></header><form id="vendorSignupForm" class="vendor-signup form"><div class="row"><label>Your full name<input name="fullName" required maxlength="120" autocomplete="name"></label><label>Phone<input name="phone" required type="tel" autocomplete="tel"></label></div><div class="row"><label>Email<input name="email" required type="email" autocomplete="email"></label><label>Password<input name="password" required type="password" minlength="8" autocomplete="new-password"></label></div><div class="row"><label>Country<select name="country" required>${api.countryOptions('PK')}</select></label><label>Gender<select name="gender" required><option value="">Select</option><option value="male">Male</option><option value="female">Female</option></select></label></div><label>Vendor invitation code<input name="invitation" required autocomplete="off" placeholder="MIO member ID"></label><label class="vendor-consent"><input type="checkbox" name="consent" required> I accept the <a href="#terms">terms and conditions</a>.</label><button class="btn primary" type="submit">Create seller account</button><p role="status"></p><p>Already registered? <button type="button" class="btn small" data-page="login">Sign in</button></p></form><div id="vendorApplicationHost"></div></div>`;
  $('main-content').append(registration);
  const application=$('sellerForm').closest('.card');$('vendorApplicationHost').append(application);application.hidden=true;
  $('sellerIntroducer').required=false;$('sellerIntroducer').removeAttribute('pattern');$('sellerReferralField').hidden=true;$('sellerExistingAccount').hidden=true;
  $('page-sell').replaceChildren();$('page-sell').innerHTML='<div id="vendorReferralDashboard"></div>';
  const seller=$('page-seller'),settlement=document.createElement('div');settlement.id='vendorSettlementPanel';settlement.className='vendor-panel';
  // Keep the existing payout form and its handlers intact.
  for(const card of [...seller.querySelectorAll(':scope>.card')])settlement.append(card);
  const brand=$('sellerBrand'),summary=$('sellerSummary');seller.replaceChildren();
  seller.innerHTML=`<div class="vendor-portal"><header class="vendor-portal-bar"><button type="button" class="vendor-menu-toggle" aria-label="Toggle seller menu" aria-expanded="false">☰</button><div><small>SELLER PORTAL</small><h1 id="vendorStoreName">Your store</h1></div><span id="vendorStoreState" class="vendor-state"></span></header><div class="vendor-portal-layout"><nav class="vendor-portal-nav" aria-label="Seller navigation">${[['overview','Overview'],['products','Products'],['orders','Orders'],['inventory','Inventory'],['settlements','Sales & settlements'],['store','Store details']].map(([key,title])=>`<button type="button" data-vendor-tab="${key}">${title}</button>`).join('')}<button type="button" data-page="support">Support</button></nav><div class="vendor-portal-main"><div class="vendor-store-selector"><label for="sellerBrand">Store</label></div><div id="vendorPending" hidden></div><div id="vendorOverview" class="vendor-panel"></div><div id="vendorProductsPanel" class="vendor-panel"></div><div id="vendorOrdersPanel" class="vendor-panel"></div><div id="vendorStorePanel" class="vendor-panel"></div></div></div></div>`;
  seller.querySelector('.vendor-store-selector').append(brand);$('vendorProductsPanel').append($('sellerProducts')||api.productSection);seller.querySelector('.vendor-portal-main').append(settlement);summary.hidden=true;settlement.prepend(summary);
  seller.addEventListener('click',e=>{const button=e.target.closest('[data-vendor-tab]');if(button){show(button.dataset.vendorTab);if(button.dataset.newProduct)api.newProduct();return}if(e.target.closest('.vendor-menu-toggle')){const open=seller.classList.toggle('vendor-menu-open');e.target.closest('button').setAttribute('aria-expanded',String(open))}const pager=e.target.closest('[data-vendor-page]');if(pager){page+=Number(pager.dataset.vendorPage);refresh().catch(api.error)}const detail=e.target.closest('[data-vendor-order]');if(detail){const panel=$(detail.dataset.vendorOrder);panel.hidden=!panel.hidden;detail.setAttribute('aria-expanded',String(!panel.hidden))}});
  $('vendorSignupForm').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('[type=submit]'),status=f.querySelector('[role=status]');if(b.disabled)return;b.disabled=true;status.textContent='Creating your seller account…';try{const r=await api.db.auth.signUp({email:f.elements.email.value.trim(),password:f.elements.password.value,options:{emailRedirectTo:location.origin+location.pathname+'#vendor-register',data:{registration_type:'vendor',vendor_invitation:f.elements.invitation.value.trim().toUpperCase(),full_name:f.elements.fullName.value.trim(),phone:f.elements.phone.value.trim(),country_code:f.elements.country.value,gender:f.elements.gender.value,terms_accepted:f.elements.consent.checked?'true':'false'}}});if(r.error)throw r.error;f.elements.password.value='';status.textContent='Check your email to verify your seller account, then sign in to complete the application.';if(r.data?.session)await api.signedUp(r.data.session)}catch(error){status.textContent=error.message}finally{b.disabled=false}};
 }
 async function identify(session){identity=session?.user.id||null;const token=++generation;access={};document.body.classList.remove('vendor-only');if(!identity)return access;const r=await api.db.rpc('my_vendor_access');if(r.error)throw r.error;if(token!==generation)return {};access=r.data||{};document.body.classList.toggle('vendor-only',!!access.vendor_only);return access}
 function show(next='overview'){tab=next;const active=next==='inventory'?'products':next;for(const [key,id] of Object.entries({overview:'vendorOverview',products:'vendorProductsPanel',orders:'vendorOrdersPanel',settlements:'vendorSettlementPanel',store:'vendorStorePanel'}))$(id).hidden=key!==active;$('page-seller').querySelectorAll('[data-vendor-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.vendorTab===next);b.setAttribute('aria-current',b.dataset.vendorTab===next?'page':'false')});$('page-seller').classList.remove('vendor-menu-open');$('page-seller').querySelector('.vendor-menu-toggle').setAttribute('aria-expanded','false');if(next==='inventory')api.inventory()}
 async function registration(){const signed=!!api.session(),allowed=api.registrationOpen();$('vendorSignupForm').hidden=signed||!allowed;const f=$('vendorSignupForm');f.elements.invitation.value=new URLSearchParams(location.search).get('vendor')||sessionStorage.getItem('mio-vendor-invite')||'';const host=$('vendorApplicationHost');host.firstElementChild.hidden=!signed||!access.email_verified||!allowed;let note=$('vendorRegistrationNote');if(!note){note=document.createElement('p');note.id='vendorRegistrationNote';host.before(note)}note.textContent=!allowed?'New vendor applications are currently closed.':signed&&!access.email_verified?'Verify your email before submitting your business details.':'';if(signed){if(access.identity){$('sellerPhone').value||=access.identity.phone;$('sellerEmail').value||=api.session().user.email||'';$('sellerCountry').value=access.identity.country_code}await api.agreement()}}
 function orderTable(rows,scope='overview'){return `<div class="vendor-table-wrap"><table><thead><tr><th>Order</th><th>Date</th><th>Amount</th><th>Status</th><th>Details</th></tr></thead><tbody>${rows.map((o,i)=>`<tr><td>${esc(o.order_code)}</td><td>${date(o.created_at)}</td><td>${money(o.amount)}</td><td><span class="vendor-pill ${o.status==='delivered'?'done':''}">${esc(o.status)}</span></td><td><button class="btn small" type="button" data-vendor-order="vendorOrder-${scope}-${i}" aria-expanded="false">View</button></td></tr><tr id="vendorOrder-${scope}-${i}" hidden><td colspan="5"><strong>Payment: ${esc(o.payment_status)}</strong>${scope==='referrals'?`<p>Your commission: ${Number(o.credited||0).toFixed(2)} MIO confirmed · ${Number(o.pending||0).toFixed(2)} MIO pending</p>`:''}<ul>${(o.items||[]).map(p=>`<li>${esc(p.name)} × ${p.quantity} · ${money(p.amount)}</li>`).join('')}</ul></td></tr>`).join('')||'<tr><td colspan="5">Your orders will appear here.</td></tr>'}</tbody></table></div>`}
 async function refresh(){const token=generation;await api.loadBrands();if(token!==generation)return;const v=api.currentVendor(),root=$('page-seller');$('vendorStoreName').textContent=v?.business_name||'Seller application';$('vendorStoreState').textContent=v?'Approved vendor':'Awaiting approval';$('vendorPending').hidden=!!v;root.querySelector('.vendor-store-selector').hidden=!v||$('sellerBrand').options.length<=1;root.querySelector('.vendor-portal-nav').hidden=!v;if(!v){show('pending');$('vendorPending').innerHTML=(access.application_status==='pending'?'<h2>Application awaiting approval</h2><p>Your business details are under review. Selling tools become available after approval.</p>':'<h2>Complete your seller application</h2><p>Business details and the company agreement are required before your store is approved.</p>')+(access.vendor_only||access.application_status?'<button class="btn primary" data-page="vendor-register">View application</button>':'<button class="btn" data-page="support">Contact support</button>');return}
  const [r,s]=await Promise.all([api.db.rpc('seller_portal_orders',{p_vendor:v.id,p_page:page}),api.db.rpc('my_brand_summary',{p_vendor_id:v.id})]);if(r.error||s.error)throw r.error||s.error;if(token!==generation)return;orders=r.data||{rows:[],total:0};const products=api.products(),stats=s.data||{},available=Number(stats.income_pkr||0)-Number(stats.reserved_pkr||0)-Number(stats.paid_pkr||0);
  $('vendorOverview').innerHTML=`<div class="vendor-section-title"><h2>Store overview</h2><span>All time</span></div><div class="vendor-metrics">${metric('Net sales',money(stats.income_pkr))}${metric('Orders',orders.total)}${metric('Live products',products.filter(p=>p.status==='approved').length)}${metric('Available payout',money(available))}</div><div class="vendor-quick-actions"><button class="btn primary" data-vendor-tab="products" data-new-product="1">＋ Add product</button><button class="btn" data-vendor-tab="inventory">Manage inventory</button></div><div class="vendor-attention">${products.filter(p=>p.status==='pending').length} listings awaiting review</div><div class="vendor-section-title"><h2>Recent orders</h2><button class="btn small" data-vendor-tab="orders">View orders →</button></div>${orderTable(orders.rows.slice(0,5))}<div class="vendor-section-title"><h2>Products</h2><button class="btn small" data-vendor-tab="products">View products →</button></div><div class="vendor-table-wrap"><table><thead><tr><th>Product</th><th>Status</th><th>Stock</th><th>Action</th></tr></thead><tbody>${products.slice(0,5).map(p=>`<tr><td><div class="vendor-product-name">${api.safeImage(p.image_url)?`<img src="${esc(api.safeImage(p.image_url))}" alt="">`:''}<b>${esc(p.name)}</b></div></td><td><span class="vendor-pill">${esc(p.status)}</span></td><td>${p.stock_quantity}</td><td><button class="btn small edit-listing" data-id="${esc(p.id)}">Edit</button></td></tr>`).join('')||'<tr><td colspan="4">Add your first product to get started.</td></tr>'}</tbody></table></div>`;
  $('vendorOrdersPanel').innerHTML=`<h2>Orders</h2>${orderTable(orders.rows,'all')}<div class="vendor-pagination"><button class="btn small" data-vendor-page="-1" ${page===1?'disabled':''}>Previous</button><span>Page ${page} · ${orders.total} orders</span><button class="btn small" data-vendor-page="1" ${page*50>=orders.total?'disabled':''}>Next</button></div>`;
  $('vendorStorePanel').innerHTML=`<h2>Store details</h2><dl class="vendor-store-details"><dt>Business</dt><dd>${esc(v.business_name)}</dd><dt>Contact email</dt><dd>${esc(v.contact_email||'—')}</dd><dt>Contact phone</dt><dd>${esc(v.contact_phone||'—')}</dd><dt>Agreed commission</dt><dd>${(Number(v.commission_rate||0)*100).toFixed(2)}%</dd><dt>Status</dt><dd>${esc(v.status)}</dd></dl><p>Contact support to request changes to your verified business details or agreement.</p><button class="btn" data-page="support">Contact support</button>`;show(tab);
 }
 let reportVendor=null,reportFrom='',reportTo='',reportRequest=0;
 function networkInvite(){const profile=api.profile(),page=$('page-network');if(!page)return;let box=$('networkVendorInvitation');if(!box){box=document.createElement('section');box.id='networkVendorInvitation';box.className='vendor-invitation';page.prepend(box)}box.hidden=!profile||!api.registrationOpen();if(!profile){box.replaceChildren();return}const url=invite(profile.member_code);box.innerHTML=`<div><h2>Vendor registration link</h2><p>Invite a business to register with your vendor network.</p><input readonly aria-label="Vendor registration link" value="${esc(url)}"></div><button class="btn primary copy-code" data-copy="${esc(url)}">Copy link</button>`;}
 async function referrals(){const token=generation,request=++reportRequest,host=$('vendorReferralDashboard');networkInvite();if(!api.profile()){host.innerHTML='<h1>My Vendors</h1><p>Sign in to your member account.</p>';return}host.setAttribute('aria-busy','true');
 try{const r=await api.db.rpc('my_vendor_report',{p_from:reportFrom||null,p_to:reportTo||null,p_vendor:reportVendor,p_page:refPage});if(r.error)throw r.error;if(token!==generation||request!==reportRequest)return;const d=r.data||{},m=d.summary||{},rows=d.vendors||[],title=reportVendor?rows[0]?.business_name||'Vendor details':'My Vendors';
 host.innerHTML=`<header class="vendor-heading"><div><small>MY VENDOR NETWORK</small><h1>${esc(title)}</h1><p>Sales and commission from vendors registered with you.</p></div><button class="btn" data-report-back>${reportVendor?'← All vendors':'← My Network'}</button></header><form class="vendor-report-filters"><label>From<input type="date" name="from" value="${esc(reportFrom)}"></label><label>To<input type="date" name="to" value="${esc(reportTo)}"></label><button class="btn primary">Apply dates</button><button type="button" class="btn" data-report-reset>All time</button></form><div class="vendor-metrics">${metric('Total vendors',m.vendors||0)}${metric('Successful sales',money(m.sales))}${metric('Products sold',m.units||0)}${metric('Total orders',m.orders||0)}${metric('Confirmed commission',Number(m.credited||0).toFixed(2)+' MIO')}${metric('Pending commission',Number(m.pending||0).toFixed(2)+' MIO')}</div><p class="note">Sales include delivered, payment-confirmed items. Cancelled/refunded orders are excluded from successful sales. Dates use Pakistan time.</p>${!reportVendor?`<h2>Your vendors</h2><div class="vendor-table-wrap"><table><thead><tr><th>Vendor</th><th>Status</th><th>Sales</th><th>Units sold</th><th>Orders</th><th>Commission</th></tr></thead><tbody>${rows.map(v=>`<tr><td><button class="btn small" data-report-vendor="${esc(v.id)}">${esc(v.business_name)} →</button></td><td>${esc(v.status)}</td><td>${money(v.sales)}</td><td>${v.units}</td><td>${v.orders}</td><td>${Number(v.credited||0).toFixed(2)} MIO</td></tr>`).join('')||'<tr><td colspan="6">No approved vendors yet. Share your registration link from My Network.</td></tr>'}</tbody></table></div>`:''}<h2>Orders</h2>${orderTable(d.orders||[],'referrals')}<div class="vendor-pagination"><button class="btn" data-report-page="-1" ${refPage<=1?'disabled':''}>Previous</button><span>Page ${refPage} · ${m.orders||0} orders</span><button class="btn" data-report-page="1" ${refPage*50>=(m.orders||0)?'disabled':''}>Next</button></div>`;
 host.querySelector('form').onsubmit=e=>{e.preventDefault();const f=e.currentTarget;if(f.elements.from.value&&f.elements.to.value&&f.elements.from.value>f.elements.to.value){api.error(new Error('Start date must not follow end date'));return}reportFrom=f.elements.from.value;reportTo=f.elements.to.value;refPage=1;referrals().catch(api.error)};
 host.onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-report-back')){if(!reportVendor){api.go('network');return}reportVendor=null;refPage=1}else if(b.dataset.reportVendor){reportVendor=b.dataset.reportVendor;refPage=1}else if(b.dataset.reportPage){refPage+=Number(b.dataset.reportPage)}else if(b.hasAttribute('data-report-reset')){reportFrom=reportTo='';refPage=1}else if(b.dataset.vendorOrder){const row=$(b.dataset.vendorOrder);row.hidden=!row.hidden;b.setAttribute('aria-expanded',String(!row.hidden));return}else return;referrals().catch(api.error)};
 }catch(error){if(token===generation&&request===reportRequest){host.innerHTML='<h1>My Vendors</h1><p role="alert">Unable to load your vendors. Please try again.</p><button class="btn" data-report-retry>Retry</button>';host.querySelector('button').onclick=()=>referrals().catch(api.error)}throw error}finally{if(request===reportRequest)host.removeAttribute('aria-busy')}
 }
 function clear(){generation++;reportRequest++;reportVendor=null;reportFrom=reportTo='';$('networkVendorInvitation')?.remove();access={};identity=null;tab='overview';page=refPage=1;document.body.classList.remove('vendor-only','seller-portal-active');['vendorReferralDashboard','vendorOverview','vendorOrdersPanel','vendorStorePanel','sellerAgreement'].forEach(id=>$(id)?.replaceChildren());$('vendorSignupForm')?.reset();$('sellerForm')?.reset();if($('vendorApplicationHost')?.firstElementChild)$('vendorApplicationHost').firstElementChild.hidden=true}
 // Capture and move existing controls rather than replacing their event handlers.
 api.productSection=$('sellerProducts');api.productSection.remove();setup();
 return {identify,registration,refresh,referrals,show,clear,invite,networkInvite,get access(){return access}};
}
window.MioVendorPortal={create};
})();
